mbr.copysrc:
     /* =================================================================== */
     /*                                                                     */
     /*  Documentation:                                                     */
     /*                                                                     */
     /*  Utility . . . : CMPMSGF                                            */
     /*  Object  . . . : A_INSTALL  (PGM)                                   */
     /*  Source member : A_INSTALL                                          */
     /*  Source type . : CLLE                                               */
     /*  Description   : CMPMSGF - Installer                                */
     /*  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      */
     /*                                                                     */
     /* =================================================================== */
     /*                                                                     */
     /*  This software is free software, you can redistribute it and/or     */
     /*  modify it under the terms of the GNU General Public License (GPL)  */
     /*  as published by the Free Software Foundation.                      */
     /*                                                                     */
     /*  See GNU General Public License for details.                        */
     /*          http://www.opensource.org                                  */
     /*          http://www.opensource.org/licenses/gpl-license.html        */
     /*                                                                     */
     /* =================================================================== */
     /*  History:                                                           */
     /*                                                                     */
     /*  Datum       Name          Änderung                                 */
     /*  ----------  ------------  ---------------------------------------  */
     /*                                                                     */
     /* =================================================================== */
     /*   >>PRE-COMPILER<<                                                  */
     /*     >>CRTCMD<<    CRTBNDCL  PGM(QTEMP/&OB) +                        */
     /*                             SRCFILE(&SL/&SF) SRCMBR(&SM);           */
     /*     >>IMPORTANT<<                                                   */
     /*       >>PARM<<    OPTION(*EVENTF);                                  */
     /*     >>END-IMPORTANT<<                                               */
     /*     >>EXECUTE<<                                                     */
     /*     >>CMD<<       CALL   PGM(QTEMP/A_INSTALL) +                     */
     /*                          PARM('*CURRENT' '&SF' '&LI' 'ENG');        */
     /*     >>CMD<<       DLTPGM PGM(QTEMP/A_INSTALL);                      */
     /*   >>END-PRE-COMPILER<<                                              */
     /* =================================================================== */
             PGM        PARM(&TGTRLS &SRCFILE &TOLIB &LNG)

             DCL        VAR(&TGTRLS   ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&SRCFILE  ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&TOLIB    ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&LNG      ) TYPE(*CHAR) LEN( 3)

             DCL        VAR(&SRCLIB   ) TYPE(*CHAR) LEN(10)

             DCL        VAR(&CRTMSGF  ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&MSGF     ) TYPE(*CHAR) LEN(10) VALUE('CMPMSGF')
             DCL        VAR(&PNLGRP   ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&CMD      ) TYPE(*CHAR) LEN(10)

             CHGVAR     VAR(&SRCLIB) VALUE(&TOLIB   )

     /* -------------------------------- */
     /*  Delete old objects              */
     /* -------------------------------- */
             DLTCMD     CMD(&TOLIB/CMPMSGF)
             MONMSG     MSGID(CPF2105)

             DLTF       FILE(&TOLIB/CMPMSGFD1)
             MONMSG     MSGID(CPF2105)

             DLTF       FILE(&TOLIB/CMPMSGFD2)
             MONMSG     MSGID(CPF2105)

             DLTPGM     PGM(&TOLIB/CMPMSGFC)
             MONMSG     MSGID(CPF2105)

             DLTPGM     PGM(&TOLIB/A_MSG_ENG)
             MONMSG     MSGID(CPF2105)

             DLTMOD     MODULE(&TOLIB/CMPMSGFC1)
             MONMSG     MSGID(CPF2105)

             DLTMOD     MODULE(&TOLIB/CMPMSGFR1)
             MONMSG     MSGID(CPF2105)

             DLTMOD     MODULE(&TOLIB/CMPMSGFR2)
             MONMSG     MSGID(CPF2105)

             DLTMOD     MODULE(&TOLIB/CMPMSGFR3)
             MONMSG     MSGID(CPF2105)

             DLTMSGF    MSGF(&TOLIB/CMPMSGF)
             MONMSG     MSGID(CPF2105)

             DLTPNLGRP  PNLGRP(&TOLIB/CMPMSGFP)
             MONMSG     MSGID(CPF2105)

             RMVMSG     PGMQ(*SAME (*)) CLEAR(*ALL)

     /* -------------------------------- */
     /*  Create message file             */
     /* -------------------------------- */
             IF         COND(&LNG *EQ 'ENG') THEN(DO)
                CHGVAR     VAR(&CRTMSGF) VALUE('A_MSG_ENG')
                CHGVAR     VAR(&PNLGRP ) VALUE('CMPMSGFPE')
                CHGVAR     VAR(&CMD    ) VALUE('CMPMSGFE')
                GOTO       CMDLBL(INSTALL)
             ENDDO

             SNDPGMMSG  MSGID(CPF9898) MSGF(QCPFMSG) MSGDTA('Invalid +
                          language parameter:' *BCAT &LNG) +
                          TOPGMQ(*PRV (*PGMBDY)) MSGTYPE(*ESCAPE)

INSTALL:
             CRTMSGF    MSGF(&TOLIB/&MSGF) +
                          TEXT('Tool: CMPMSGF    (Compare Message File)')

             CRTCLPGM   PGM(QTEMP/&CRTMSGF) +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(*PGM) +
                          OPTION(*LSTDBG) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(&CRTMSGF  ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CALL       PGM(QTEMP/&CRTMSGF) PARM(&TOLIB)
             DLTPGM     PGM(QTEMP/&CRTMSGF)

     /* -------------------------------- */
     /*  Display files                   */
     /* -------------------------------- */
             CRTDSPF    FILE(&TOLIB/CMPMSGFD1) +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(*FILE) +
                          RSTDSP(*YES)
             DLTSPLF    FILE(CMPMSGFD1) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CRTDSPF    FILE(&TOLIB/CMPMSGFD2) +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(*FILE) +
                          RSTDSP(*YES)
             DLTSPLF    FILE(CMPMSGFD2) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

     /* -------------------------------- */
     /*  Create modules                  */
     /* -------------------------------- */
             CRTCLMOD   MODULE(&TOLIB/CMPMSGFC1) +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(*MODULE) +
                          DBGVIEW(*LIST) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(CMPMSGFC1) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CRTRPGMOD  MODULE(&TOLIB/CMPMSGFR1) +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(*MODULE) +
                          DBGVIEW(*LIST) TRUNCNBR(*NO) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(CMPMSGFR1) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CRTRPGMOD  MODULE(&TOLIB/CMPMSGFR2) +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(*MODULE) +
                          DBGVIEW(*LIST) TRUNCNBR(*NO) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(CMPMSGFR2) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CRTRPGMOD  MODULE(&TOLIB/CMPMSGFR3) +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(*MODULE) +
                          DBGVIEW(*LIST) TRUNCNBR(*NO) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(CMPMSGFR3) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

     /* -------------------------------- */
     /*  Create programs                 */
     /* -------------------------------- */
             CRTPGM     PGM(&TOLIB/CMPMSGFC) +
                          MODULE(&TOLIB/CMPMSGFC1   +
                                 &TOLIB/CMPMSGFR1   +
                                 &TOLIB/CMPMSGFR2   +
                                 &TOLIB/CMPMSGFR3)  +
                          ENTMOD(&TOLIB/CMPMSGFC1)  +
                          DETAIL(*BASIC)            +
                          ACTGRP(*NEW)              +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(CMPMSGFC  ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

     /* -------------------------------- */
     /*  Create panel groups             */
     /* -------------------------------- */
             CRTPNLGRP PNLGRP(&TOLIB/CMPMSGFP  ) +
                          SRCFILE(&SRCLIB/&SRCFILE) +
                          SRCMBR(&PNLGRP)
             DLTSPLF    FILE(CMPMSGFP  ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

     /* -------------------------------- */
     /*  Create commands                 */
     /* -------------------------------- */
             CRTCMD     CMD(&TOLIB/CMPMSGF   )                   +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(&CMD) +
                          PGM(&TOLIB/CMPMSGFC  )                 +
                          HLPSCHIDX(*NONE)                       +
                          HLPPNLGRP(*LIBL/CMPMSGFP  )            +
                          HLPID(CMPMSGF   )                      +
                          PRDLIB(&TOLIB)                         +
                          MSGF(*LIBL/CMPMSGF)
             DLTSPLF    FILE(&CMD      ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

     /* -------------------------------- */
     /*  Delete obsolete objects         */
     /* -------------------------------- */
             DLTMOD     MODULE(&TOLIB/CMPMSGFC1)
             DLTMOD     MODULE(&TOLIB/CMPMSGFR1)
             DLTMOD     MODULE(&TOLIB/CMPMSGFR2)
             DLTMOD     MODULE(&TOLIB/CMPMSGFR3)

             ENDPGM

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0001                    */
     /* You pressed an invalid function key.                        */
     /* ----------------------------------------------------------- */

             PGM        PARM(&LI      )

             DCL        VAR(&LI       ) TYPE(*CHAR) LEN(10)

             RMVMSGD MSGID(USR0001) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0001) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'You pressed an invalid function key.'                                +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0002                    */
     /* Combination not allowed.                                    */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0002) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0002) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Combination not allowed.'                                            +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0003                    */
     /* Already at top of subfile.                                  */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0003) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0003) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Already at top of subfile.'                                          +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0004                    */
     /* Already at botton of subfile.                               */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0004) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0004) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Already at botton of subfile.'                                       +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0005                    */
     /* No more records available.                                  */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0005) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0005) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'No more records available.'                                          +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0006                    */
     /* Option &1 is not valid.                                     */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0006) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0006) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Option &1 is not valid.'                                             +
                ) +
                SEV(00) +
                FMT( +
                    (*QTDCHAR 002) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0007                    */
     /* No data in subfile.                                         */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0007) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0007) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'No data in subfile.'                                                 +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0008                    */
     /* Reading ...                                                 */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0008) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0008) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Reading ...'                                                         +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0009                    */
     /* Warning: Not all entries loaded!                            */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0009) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0009) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Warning: Not all entries loaded!'                                    +
                ) +
                SECLVL(+
'&N &N Cause . . . . . :   Not all entries could be loaded into the su-
bfile. The subfile has reached its limit of &1 items. Use the "Positio-
n to" to move to another starting point.'                             +
                ) +
                SEV(00) +
                FMT( +
                    (*DEC 005 0) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0010                    */
     /* New and old message file must be different.                 */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0010) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0010) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'New and old message file must be different.'                         +
                ) +
                SEV(00) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0011                    */
     /* Abnormal program end. See job log for details.              */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0011) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0011) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Abnormal program end. See job log for details.'                      +
                ) +
                SEV(30) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

             RCLRSC LVL(*)

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0012                    */
     /* Message file &1 is alredy open.                             */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0012) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0012) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Message file &1 is already open.'                                    +
                ) +
                SEV(00) +
                FMT( +
                    (*DEC 005 0) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0013                    */
     /* Message file &1 is not open.                                */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0013) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0013) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Message file &1 is not open.'                                        +
                ) +
                SEV(00) +
                FMT( +
                    (*DEC 005 0) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0014                    */
     /* Message file &1 is not open.                                */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0014) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0014) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Library & does not exist.'                                           +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR 010) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0015                    */
     /* Message file &1 is not open.                                */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0015) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0015) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Message file &1 in library &2 does not exist.'                       +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR 010) +
                    (*CHAR 010) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0016                    */
     /* Could not copy message ID &1. See job log for details.      */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0016) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0016) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Could not copy message ID &1. See job log for details.'              +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR 007) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0017                    */
     /* Press &1 to confirm.                                        */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0017) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0017) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Press &1 to confirm.'                                                +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR 010) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0018                    */
     /* Lower range limit greater than upper range limit.           */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0018) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0018) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Lower range limit greater than upper range limit.'                   +
                ) +
                SEV(00) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0019                    */
     /* Choose Y or N.                                              */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0019) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0019) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Choose Y or N.'                                                      +
                ) +
                SEV(00) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0020                    */
     /* Compare level *YES not allowed without compare date *YES.   */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0020) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0020) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Compare level *YES not allowed without compare date *YES.'           +
                ) +
                SEV(00) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0021                    */
     /* PTF missing. CMPMSGF has to use the RTVM0300 format.        */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0021) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0021) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'PTF missing. CMPMSGF has to use the RTVM0300 format.'                +
                ) +
                SECLVL(+
'&N &N Cause . . . . . :   A PTF is missing. CMPMSGF can not use the -
RTVM0400 format to get better results. Please refer to the online help -
for more information.'                                                +
                ) +
                SEV(00) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0022                    */
     /* Message description &1 not found in message file &2 in &3.  */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0022) MSGF(&LI/CMPMSGF)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0022) +
                MSGF(&LI/CMPMSGF) +
                MSG(+
'Message description &1 not found in message file &2 in &3.'          +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR 007) +
                    (*CHAR 010) +
                    (*CHAR 010) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

             RCLRSC LVL(*)

             ENDPGM

