     H DEBUG
     H NOMAIN
     H EXTBININT(*YES)
     H OPTION(*SRCSTMT : *NODEBUGIO)
     H DECEDIT('0,') DATEDIT(*DMY.)
     H DATFMT(*ISO )  TIMFMT(*ISO )
     H EXPROPTS(*RESDECPOS)
      /COPY QCMPMSGF,COPYRIGHT
       //===============================================================*
     FCMPMSGFD1 CF   E             WORKSTN usropn
     F                                     infds(Screen)
     F                                     indds(workstn)
     F                                     sfile(SFL:SFLRRN)

     D workstn         DS                  qualified
     D  cd_white              50     50N
     D  cd_grn                51     51N
     D  cd_ylw                52     52N
     D  cd_red                53     53N
     D  msgf1_pc              61     61N
     D  lib1_pc               62     62N
     D  msgf2_pc              65     65N
     D  lib2_pc               66     66N
     D  msgf1_ri              71     71N
     D  lib1_ri               72     72N
     D  msgf2_ri              75     75N
     D  lib2_ri               76     76N
     D  sfldsp                80     80N
     D  sfldspctl             81     81N
     D  sflclr                82     82N
     D  sflend                83     83N
     D  sflmode               84     84N
     D  sflnxtchg             85     85N
     D  opt_ri                86     86N
     D  posto_ri              87     87N
     D  find_ri               88     88N
     D  msgsflend             89     89N
     D  options_1             91     91N
     D  options_2             92     92N
     D  options_3             93     93N

       //== Workstation information data structure =====================*
     D screen          DS                  qualified
     D Open                    9      9A
     D status                 11     15S 0
     D AID                   369    369A
       //===============================================================*

       //== Prototypes and Constants ===================================*
      /COPY QCMPMSGF,CMPMSGFR4
       //===============================================================*

       //== Private Prototypes =========================================*
       //  ... end program
     D cmd_endPgm...
     D                 PR              N

       //  ... refresh screen
     D cmd_refresh...
     D                 PR
     D  i_lowerMsgID                  7A   value
     D  i_upperMsgID                  7A   value

       //  ... process
     D cmd_process...
     D                 PR              N
     D  o_msg                                     like(msg_t     )

       //  ... goto top of subfile
     D cmd_gotoTop...
     D                 PR

       //  ... goto botton of subfile
     D cmd_gotoBot...
     D                 PR

       //  ... show more cmd keys
     D cmd_moreKeys...
     D                 PR

       //  ... show more options
     D cmd_moreOptions...
     D                 PR

       //  ... command line
     D cmd_cmdLine...
     D                 PR

       //  ... process enter key
     D cmd_enter...
     D                 PR              N
     D  i_lowerMsgID                  7A   value
     D  i_upperMsgID                  7A   value

       //  ... page up
     D cmd_pageUp...
     D                 PR

       //  ... page down
     D cmd_pageDown...
     D                 PR

       //  ... validate screen
     D f_validateScreen...
     D                 PR              N

       //  ... read changed records
     D f_sflReadChg...
     D                 PR              N

       //  ... check if there are changed records
     D f_sflChkChg...
     D                 PR              N
     D  o_sflRrn                     10I 0        options(*nopass)

       //  ... initialize subfile
     D p_sflInit...
     D                 PR

       //  ... position file pointer and read first record
     D p_sflPosKey...
     D                 PR              N
     D  i_lowerMsgID                  7A   value

       //  ... read next record
     D f_sflReadRcd...
     D                 PR              N

       //  ... load page into subfile
     D f_sflLoadPage...
     D                 PR              N
     D  i_lowerMsgID                  7A   value
     D  i_upperMsgID                  7A   value

       //  ... clear selection
     D p_sflClrSlc...
     D                 PR
     D  i_sflRrn                     10I 0 const

       //  ... set error status
     D p_sflsetErr...
     D                 PR
     D  i_sflRrn                     10I 0 const

       //  ... clear subfile/screen indicators
     D p_sflClrInd...
     D                 PR

       //  ... position to
     D p_sflPosTo...
     D                 PR
     D  i_posTo                            value  like(##POSTO   )

       //  ... get first message id
     D f_getFirstMsgID...
     D                 PR              N
     D  i_msgId                       7A   value
     D  i_msgF                       10A   value
     D  i_lib                        10A   value
     D  o_msgID                       7A

       //  ... retrieve message text
     D f_rtvMsgText...
     D                 PR          1024A
     D  i_rtvm0400                         value  likeds(RTVM0400_t)

       //  ... retrieve message help
     D f_rtvMsgHelp...
     D                 PR          1024A
     D  i_rtvm0400                         value  likeds(RTVM0400_t)

       //  ... retrieve replacement variables
     D f_rtvRplVars...
     D                 PR          1024A
     D  i_rtvm0400                         value  likeds(RTVM0400_t)

       //  ... open message file 1
     D p_openMsgF1...
     D                 PR
     D  i_msgF                       10A   value
     D  i_lib                        10A   value

       //  ... open message file 2
     D p_openMsgF2...
     D                 PR
     D  i_msgF                       10A   value
     D  i_lib                        10A   value

       //  ... close message file 1
     D p_closeMsgF1...
     D                 PR

       //  ... close message file 2
     D p_closeMsgF2...
     D                 PR

       //  ... is message file 1 open?
     D f_isOpenMsgF1...
     D                 PR              N

       //  ... is message file 2 open?
     D f_isOpenMsgF2...
     D                 PR              N

       //  ... get message file library
     D f_getMsgFLib...
     D                 PR            10A
     D  i_msgF                       10A   value
     D  i_lib                        10A   value

       //  ... check if message file exists
     D f_chkMsgF...
     D                 PR              N
     D  i_msgF                       10A   value
     D  i_lib                        10A   value
     D  o_msg                                     like(msg_t     )

       //  ... change subfile action code
     D p_sflChgCode...
     D                 PR
     D  i_rrn                        10I 0 value
