       //  ... subfile add message ID
     D f_sflAddMsgID...
     D                 PR              N
     D  i_rrn                        10I 0 value
     D  i_code                        1A   value

       //  ... subfile change message ID
     D f_sflChgMsgID...
     D                 PR              N
     D  i_rrn                        10I 0 value
     D  i_code                        1A   value

       //  ... subfile delete message ID
     D f_sflDltMsgID...
     D                 PR              N
     D  i_rrn                        10I 0 value
     D  i_code                        1A   value

       //  ... subfile display message ID
     D f_sflDspMsgID...
     D                 PR              N
     D  i_rrn                        10I 0 value
     D  i_code                        1A   value

       //  ... add message id
     D f_addMsgID...
     D                 PR              N
     D  i_msgID                       7A   value
     D  i_msgF                       10A   value
     D  i_lib                        10A   value
