       //==================================================================*
       //  Check if Message File 1 is open.
       //==================================================================*
     P f_isOpenMsgF1...
     P                 B
     D                 PI              N

       //  Return value
     D isOpen          S               N   inz
       //-------------------------------------------------------------------
      /FREE

       If (g_qMsgF_1 = '');
