       Endif;

       Return isOpen;

      /END-FREE
     P                 E

       //==================================================================*
       //  Get Message File Library.
       //==================================================================*
     P f_getMsgFLib...
     P                 B
     D                 PI            10A
     D  i_msgF                       10A   value
     D  i_lib                        10A   value

       //  Return Value
     D lib             S             10A   inz

       //  Fields
     D qObj            DS                  likeds(qObj_t) inz
     D OBJD0100        DS                  likeds(objd0100_t) inz
       //-------------------------------------------------------------------
      /FREE

       qObj.name = i_msgF;
       qObj.lib = i_lib;

       QUSROBJD(OBJD0100: %size(OBJD0100): 'OBJD0100': qObj: '*MSGF');

       lib = OBJD0100.rtnLib;

       Return lib;

      /END-FREE
     P                 E

       //==================================================================*
       //  Check Message File.
       //==================================================================*
     P f_chkMsgF...
     P                 B
     D                 PI              N
     D  i_msgF                       10A   value
     D  i_lib                        10A   value
     D  o_msg                                     like(msg_t     )

       //  Fields
      /COPY QCMPMSGF,USR0014
      /COPY QCMPMSGF,USR0015
       //-------------------------------------------------------------------
      /FREE

       //  Check Library ...
       If (i_lib = '');
          i_lib = '*LIBL';
       Endif;

       If (%subst(i_lib: 1: 1) <> '*');
          If (not f_exist(i_lib: '*LIBL': '*LIB'));
             Clear USR0014;
             USR00141 = i_lib;
             o_msg = f_newMsg('USR0014': USR0014);
             Return cFalse;
          Endif;
       Endif;

       //  Check message file ...
       If (not f_exist(i_msgF: i_lib: '*MSGF'));
          Clear USR0015;
          USR00151 = i_msgF;
          USR00152 = i_lib;
          o_msg = f_newMsg('USR0015': USR0015);
          Return cFalse;
       Endif;

       Return cTrue;

      /END-FREE
     P                 E

       //==================================================================*
       //  Change code.
       //==================================================================*
     P p_sflChgCode...
     P                 B
     D                 PI
     D  i_rrn                        10I 0 value
     D  i_newCode                          value  like($$CD)
       //-------------------------------------------------------------------
      /FREE

       Chain i_rrn SFL;
       $$CD = i_newCode;
       p_sflSetCdColor($$CD);
       Update SFL;

      /END-FREE
     P                 E

       //==================================================================*
       //  Add message ID.
       //==================================================================*
     P f_sflAddMsgID...
     P                 B
     D                 PI              N
     D  i_rrn                        10I 0 value
     D  i_code                        1A   value

       //  Return value
     D isAdded         S               N   inz(cFalse)

       //  Fields
     D msg             DS                  likeds(msg_t) inz

       //  Messages
      /COPY QCMPMSGF,USR0022
       //-------------------------------------------------------------------
      /FREE

       Chain i_rrn SFL;

       //  Copy message description ...
       Select;
          //  ... from right to left
       When (i_code = 'L');
          If (H_MSGID2 <> '');
             isAdded = f_copyMsgID(H_MSGID2: H_FILE2: H_LIB2: H_FILE1: H_LIB1);
          Else;
             isAdded = cFalse;
             Clear USR0022;
             USR00221 = $$MSGID;
             USR00222 = H_FILE2;
             USR00223 = H_LIB2;
             msg = f_newMsg('USR0022': USR0022);
             p_sndPgmMsg(msg: cMsg_Same: cMsg_ToPgmBdy);
          Endif;
          //  ... from left to right
       When (i_code = 'R');
          If (H_MSGID1 <> '');
             isAdded = f_copyMsgID(H_MSGID1: H_FILE1: H_LIB1: H_FILE2: H_LIB2);
          Else;
             isAdded = cFalse;
             Clear USR0022;
             USR00221 = $$MSGID;
             USR00222 = H_FILE1;
             USR00223 = H_LIB1;
             msg = f_newMsg('USR0022': USR0022);
             p_sndPgmMsg(msg: cMsg_Same: cMsg_ToPgmBdy );
          Endif;
          //  ... invalid code
       Other;
          isAdded = cFalse;
       Endsl;

       If (isAdded);
          p_sflRfrRcd(i_rrn);
       Endif;

       Return isAdded;

      /END-FREE
     P                 E

       //==================================================================*
       //  Change message ID.
       //==================================================================*
     P f_sflChgMsgID...
     P                 B
     D                 PI              N
     D  i_rrn                        10I 0 value
     D  i_code                        1A   value

       //  Return value
     D isChanged       S               N   inz(cFalse)
       //-------------------------------------------------------------------
      /FREE

       Chain i_rrn SFL;

       Select;
       When (i_code = 'L');
          isChanged = f_changeMsgID(H_MSGID1: H_FILE1: H_LIB1);
       When (i_code = 'R');
          isChanged = f_changeMsgID(H_MSGID2: H_FILE2: H_LIB2);
       Other;
          isChanged = cFalse;
       Endsl;

       If (isChanged);
          p_sflRfrRcd(i_rrn);
       Endif;

       Return isChanged;

      /END-FREE
     P                 E

       //==================================================================*
       //  Delete message ID.
       //==================================================================*
     P f_sflDltMsgID...
     P                 B
     D                 PI              N
     D  i_rrn                        10I 0 value
     D  i_code                        1A   value

       //  Return value
     D isDeleted       S               N   inz(cFalse)
       //-------------------------------------------------------------------
      /FREE

       Chain i_rrn SFL;

       Select;
       When (i_code = 'L');
          isDeleted = f_deleteMsgID(H_MSGID1: H_FILE1: H_LIB1);
       When (i_code = 'R');
          isDeleted = f_deleteMsgID(H_MSGID2: H_FILE2: H_LIB2);
       Other;
          isDeleted = cFalse;
       Endsl;

       If (isDeleted);
          p_sflRfrRcd(i_rrn);
       Endif;

       Return isDeleted;

      /END-FREE
     P                 E

       //==================================================================*
       //  Display message ID.
       //==================================================================*
     P f_sflDspMsgID...
     P                 B
     D                 PI              N
     D  i_rrn                        10I 0 value
     D  i_code                        1A   value

       //  Return value
     D isDisplayed     S               N   inz(cFalse)
       //-------------------------------------------------------------------
      /FREE

       Chain i_rrn SFL;

       Select;
       When (i_code = 'L');
          isDisplayed = f_displayMsgID(H_MSGID1: H_FILE1: H_LIB1);
       When (i_code = 'R');
          isDisplayed = f_displayMsgID(H_MSGID2: H_FILE2: H_LIB2);
       Other;
          isDisplayed = cFalse;
       Endsl;

       Return isDisplayed;

      /END-FREE
     P                 E

       //==================================================================*
       //  Copy Message ID.
       //==================================================================*
     P f_copyMsgID...
     P                 B
     D                 PI              N
     D  i_msgID                       7A   value
     D  i_fromMsgF                   10A   value
     D  i_fromLib                    10A   value
     D  i_toMsgF                     10A   value
     D  i_toLib                      10A   value

       //  Return value
     D isCopied        S               N   inz

       //  Fields
     D cmd             S            512A   inz
       //-------------------------------------------------------------------
      /FREE

       cmd = 'MRGMSGF ' +
               'FROMMSGF(' + %trim(i_fromLib) + '/' + %trim(i_fromMsgF) + ') ' +
               'TOMSGF(' + %trim(i_toLib) + '/' + %trim(i_toMsgF) + ') ' +
               'RPLMSGF(' + %trim('*NONE') + ') ' +
               'SELECT(' + %trim(i_msgID) + ') ';
       If (system(cmd) <> 0);
          isCopied = cFalse;
       Else;
          isCopied = cTrue;
       Endif;

       Return isCopied;

      /END-FREE
     P                 E

       //==================================================================*
       //  Add Message ID.
       //==================================================================*
     P f_addMsgID...
     P                 B
     D                 PI              N
     D  i_msgID                       7A   value
     D  i_msgF                       10A   value
     D  i_lib                        10A   value
     D  i_baseMsgF                   10A   value
     D  i_baseLib                    10A   value

       //  Return value
     D isAdded         S               N   inz

       //  Fields
     D cmd             S            512A   inz
       //-------------------------------------------------------------------
      /FREE

       cmd = '?ADDMSGD ' +
                '?*MSGID(' + %trim(i_msgID) + ') ' +
                '?*MSGF(' + %trim(i_lib) + '/' + %trim(i_msgF) + ') ' +
                f_rtvCmdValues(i_msgID: i_baseMsgF: i_baseLib);
       If (system(cmd) <> 0 and EXCP_MSGID <> 'CPF6801');
          isAdded = cFalse;
       Else;
          isAdded = cTrue;
       Endif;

       Return isAdded;

      /END-FREE
     P                 E

       //==================================================================*
       //  Change Message ID.
       //==================================================================*
     P f_changeMsgID...
     P                 B
     D                 PI              N
     D  i_msgID                       7A   value
     D  i_msgF                       10A   value
     D  i_lib                        10A   value

       //  Return value
     D isChanged       S               N   inz

       //  Fields
     D cmd             S           8192A   inz
     D msgHelp         S           1024A   inz
     D rplVars         S           1024A   inz
     D qMsgF           DS                  likeds(qObj_t) inz
     D rtvm0400        DS                  likeds(rtvm0400_t) inz
     D errCode         DS                  likeds(errCode_t) inz
       //-------------------------------------------------------------------
      /FREE

       qMsgF.name = i_msgF;
       qMsgF.lib = i_lib;
       rtvm0400 = f_rtvMsgD(i_msgID: qMsgF: cMSGID_SAME: errCode);

       If (f_isApiErr(errCode) or rtvm0400.bytAvl = 0);
          isChanged = cFalse;
       Else;

          //  Get second level text
          msgHelp = f_rtvMsgHelp(rtvm0400);
          If (msgHelp = '');
             msgHelp = '*N';
          Else;
             msgHelp = cQuote + %trimR(msgHelp) + cQuote;
          Endif;

          //  Get replacement variables
          rplVars = f_rtvRplVars(rtvm0400);
          If (rplVars = '');
             rplVars = '*N';
          Endif;

          //  Produce CHGMSGD command
          cmd = '?CHGMSGD ' +
                   '?*MSGID(' + %trim(i_msgID) + ') ' +
                   '?*MSGF(' + %trim(i_lib) + '/' + %trim(i_msgF) + ') ' +
                   f_rtvCmdValues(i_msgID: i_msgF: i_lib);
          If (system(cmd) <> 0 and EXCP_MSGID <> 'CPF6801');
             isChanged = cFalse;
          Else;
             isChanged = cTrue;
          Endif;
       Endif;

       Return isChanged;

      /END-FREE
     P                 E

       //==================================================================*
       //  Delete Message ID.
       //==================================================================*
     P f_deleteMsgID...
     P                 B
     D                 PI              N
     D  i_msgID                       7A   value
     D  i_msgF                       10A   value
     D  i_lib                        10A   value

       //  Return value
     D isDeleted       S               N   inz

       //  Fields
     D cmd             S            512A   inz
       //-------------------------------------------------------------------
      /FREE

       cmd = '?RMVMSGD ' +
                '?*MSGID(' + %trim(i_msgID) + ') ' +
                '?*MSGF(' + %trim(i_lib) + '/' + %trim(i_msgF) + ') ';
       If (system(cmd) <> 0 and EXCP_MSGID <> 'CPF6801');
          isDeleted = cFalse;
       Else;
          isDeleted = cTrue;
       Endif;

       Return isDeleted;

      /END-FREE
     P                 E

       //==================================================================*
       //  Display Message ID.
       //==================================================================*
     P f_displayMsgID...
     P                 B
     D                 PI              N
     D  i_msgID                       7A   value
     D  i_msgF                       10A   value
     D  i_lib                        10A   value

       //  Return value
     D isDisplayed     S               N   inz

       //  Fields
     D cmd             S            512A   inz
       //-------------------------------------------------------------------
      /FREE

       cmd = 'DSPMSGD ' +
                'RANGE(' + %trim(i_msgID) + ') ' +
                'MSGF(' + %trim(i_lib) + '/' + %trim(i_msgF) + ') ';
       If (system(cmd) <> 0);
          isDisplayed = cFalse;
       Else;
          isDisplayed = cTrue;
       Endif;

       Return isDisplayed;

      /END-FREE
     P                 E

       //==================================================================*
       //  Fill Subfile Record.
       //==================================================================*
     P p_sflFilRcd...
     P                 B
     D                 PI
     D  i_rtvm0400_1                       value  likeds(RTVM0400_t)
     D  i_rtvm0400_2                       value  likeds(RTVM0400_t)

       //  Fields
     D                 DS
     D date7$                         7A
     D date7                          7S 0 inz overlay(date7$: 1)
     D mod_1           DS                  qualified
     D  crtDate                        D   inz
     D  crtLvl                       10I 0 inz
     D  modDate                        D   inz
     D  modLvl                       10I 0 inz
     D mod_2           DS                  qualified
     D  crtDate                        D   inz
     D  crtLvl                       10I 0 inz
     D  modDate                        D   inz
     D  modLvl                       10I 0 inz
       //-------------------------------------------------------------------
      /FREE

       //  Compare date : Y/N
       If (g_cmpDate = 'Y');
          // keep information
       Else;
          i_RTVM0400_1.crtDate = cLowDat7;
          i_RTVM0400_1.modDate = cLowDat7;
          i_RTVM0400_2.crtDate = cLowDat7;
          i_RTVM0400_2.modDate = cLowDat7;
       Endif;

       //  Compare level: Y/N
       If (g_cmpLvl  = 'Y');
          // keep information
       Else;
          i_RTVM0400_1.crtLvlNbr = 0;
          i_RTVM0400_1.modLvlNbr = 0;
          i_RTVM0400_2.crtLvlNbr = 0;
          i_RTVM0400_2.modLvlNbr = 0;
       Endif;

       //  Create creation/modification level data structure
       date7$ = i_RTVM0400_1.crtDate;
      /END-FREE
     C     *CYMD         Move      date7         mod_1.crtDate
      /FREE
       date7$ = i_RTVM0400_1.modDate;
      /END-FREE
     C     *CYMD         Move      date7         mod_1.modDate

      /FREE
       mod_1.crtLvl = i_RTVM0400_1.crtLvlNbr;
       mod_1.modLvl = i_RTVM0400_1.modLvlNbr;

       date7$ = i_RTVM0400_2.crtDate;
      /END-FREE
     C     *CYMD         Move      date7         mod_2.crtDate
      /FREE
       date7$ = i_RTVM0400_2.modDate;
      /END-FREE
     C     *CYMD         Move      date7         mod_2.modDate

      /FREE
       mod_2.crtLvl = i_RTVM0400_2.crtLvlNbr;
       mod_2.modLvl = i_RTVM0400_2.modLvlNbr;

       //  Set subfile hidden fields ...
       H_MSGID1 = i_RTVM0400_1.msgId;
       H_FILE1 = g_qMsgF_1.name;
       H_LIB1 = g_qMsgF_1.lib;
       H_MSGID2 = i_RTVM0400_2.msgId;
       H_FILE2 = g_qMsgF_2.name;
       H_LIB2 = g_qMsgF_2.lib;

       //  Set subfile fields ...
       ##OPT          = '';
       workstn.opt_ri = cFalse;

       If (i_RTVM0400_1.msgId <> '');
          $$MSGID = i_RTVM0400_1.msgId;
       Else;
          $$MSGID = i_RTVM0400_2.msgId;
       Endif;

       $$TEXT1 = f_rtvMsgText(i_RTVM0400_1);
       $$HELP1 = f_rtvMsgHelp(i_RTVM0400_1);

       $$TEXT2 = f_rtvMsgText(i_RTVM0400_2);
       $$HELP2 = f_rtvMsgHelp(i_RTVM0400_2);

       //  ... determine action code
       Select;
          //  ... no-action     (missing both descriptions)
       When (i_RTVM0400_1.msgId = '' and i_RTVM0400_2.msgId = '');
          $$CD = cCmpNoAction;
          //  ... copy-to-left  (missing left description)
       When (i_RTVM0400_1.msgId = '');
          $$CD = cCmpCopyLeft;
          //  ... copy-to-right (missing right description)
       When (i_RTVM0400_2.msgId = '');
          $$CD = cCmpCopyRight;
       Other;
          //  ... others
          If (i_RTVM0400_1 = i_RTVM0400_2);
             //  ... equal descriptions
             $$CD = cCmpEqual;
          Else;

             //  ... not equal so ...
             Select;
                //  ... copy-to-left
             When (mod_2 > mod_1);
                $$CD = cCmpCopyLeft;
                //  ... copy-to-right
             When (mod_1 > mod_2);
                $$CD = cCmpCopyRight;
                //  ... don't know what to do
             Other;
                $$CD = cCmpNotEqual;
             Endsl;

          Endif;
       Endsl;

       p_sflSetCdColor($$CD);

      /END-FREE
     P                 E

       //==================================================================*
       //  Set Code Color.
       //==================================================================*
     P p_sflSetCdColor...
     P                 B
     D                 PI
     D  i_cd                               value  like($$CD      )
       //-------------------------------------------------------------------
      /FREE

       workstn.cd_white = *off;
       workstn.cd_grn = *off;
       workstn.cd_ylw = *off;
       workstn.cd_red = *off;

       Select;
       When (i_cd = cCmpCopyLeft);
          workstn.cd_ylw = *on;
       When (i_cd = cCmpCopyRight);
          workstn.cd_ylw = *on;
       When (i_cd = cCmpNotEqual);
          workstn.cd_red = *on;
       Other;
          workstn.cd_white = *on;
       Endsl;

      /END-FREE
     P                 E

       //==================================================================*
       //  Refresh Subfile Record.
       //==================================================================*
     P p_sflRfrRcd...
     P                 B
     D                 PI
     D  i_rrn                        10I 0 value

       //  Fields
     D qMsgF_1         DS                  likeds(qObj_t) inz
     D qMsgF_2         DS                  likeds(qObj_t) inz
     D rtvm0400_1      DS                  likeds(rtvm0400_t) inz
     D rtvm0400_2      DS                  likeds(rtvm0400_t) inz
     D errCode_1       DS                  likeds(errCode_t) inz
     D errCode_2       DS                  likeds(errCode_t) inz
       // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
      /FREE

       //  Retrieve message description of 1. file
       qMsgF_1.name = ##MSGF1;
       qMsgF_1.lib = ##LIB1;
       RTVM0400_1 = f_rtvMsgD($$MSGID: qMsgF_1: cMSGID_SAME: errCode_1);

       If (f_isApiErr(errCode_1) or rtvm0400_1.bytAvl = 0 );
          rtvm0400_1 = f_newRtvm0400;
       Endif;

       //  Retrieve message description of 2. file
       qMsgF_2.name = ##MSGF2;
       qMsgF_2.lib = ##LIB2;
       rtvm0400_2 = f_rtvMsgD($$MSGID: qMsgF_2: cMSGID_SAME: errCode_2);

       If (f_isApiErr(errCode_2) or rtvm0400_2.bytAvl = 0);
          rtvm0400_2 = f_newRtvm0400;
       Endif;

       Chain i_rrn SFL;

       p_sflFilRcd(RTVM0400_1: RTVM0400_2);

       Update SFL;

      /END-FREE
     P                 E

       //==================================================================*
       //  Retrieve Message Description.
       //==================================================================*
     P f_rtvMsgD...
     P                 B
     D                 PI                  likeds(rtvm0400_t)
     D  i_msgId                       7A   value
     D  i_qMsgF                            value like(qobj_t)
     D  i_rtvOpt                     10A   value
     D  o_errCode                          value likeds(errCode_t)

       //  Fields
     D RTVM0300        DS                  likeds(rtvm0300_t) inz
     D rtvm0400        DS                  likeds(rtvm0400_t) inz
     D msg             DS                  likeds(msg_t) inz
     D sizeAdj         S             10I 0 inz static
       // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
      /FREE

       rtvm0400 = f_newRtvm0400;
       o_errCode  = f_newApiErrCode(cTrue);

       //  Retrieve message description
       If (g_fmtName = 'RTVM0400');
          QMHRTVM(rtvm0400: %size(rtvm0400): g_fmtName: i_msgId: i_qMsgF
                  : '': 0: '*NO': '*YES': o_errCode: i_rtvOpt: 0: 0);

          If (o_errCode.excId = 'CPF3C21');
             sizeAdj = %size(rtvm0400) - %size(RTVM0300);
             g_fmtName = 'RTVM0300';
             msg = f_newMsg('USR0021');
             p_sndPgmMsg(msg: cMsg_Same: cMsg_ToPgmBdy);
          Endif;
       Endif;

       If (g_fmtName = 'RTVM0300');
          RTVM0300 = f_newRtvm0300;
          QMHRTVM(RTVM0300: %size(RTVM0300): g_fmtName: i_msgId: i_qMsgF
                  :'' : 0: '*NO': '*YES': o_errCode: i_rtvOpt: 0: 0);
          rtvm0400 = f_newRtvm0400;
          rtvm0400.BYTRET = RTVM0300.BYTRET;
          rtvm0400.BYTAVL = RTVM0300.BYTAVL;
          rtvm0400.MSGSEV = RTVM0300.MSGSEV;
          rtvm0400.ALTIDX = RTVM0300.ALTIDX;
          rtvm0400.ALTOPT = RTVM0300.ALTOPT;
          rtvm0400.LOGIND = RTVM0300.LOGIND;
          rtvm0400.MSGID = RTVM0300.MSGID;
          rtvm0400.reserved_01 = RTVM0300.reserved_01;

          rtvm0400.NUMVARFMT = RTVM0300.NUMVARFMT;
          rtvm0400.CSINDTXT = RTVM0300.CSINDTXT;
          rtvm0400.CSINDDTA = RTVM0300.CSINDDTA;
          rtvm0400.CCSIDTXT = RTVM0300.CCSIDTXT;
          rtvm0400.OFSDFTR = RTVM0300.OFSDFTR + sizeAdj;
          rtvm0400.LENDFTRPYR = RTVM0300.LENDFTRPYR;
          rtvm0400.LENDFTRPYA = RTVM0300.LENDFTRPYA;
          rtvm0400.OFSMSG = RTVM0300.OFSMSG + sizeAdj;
          rtvm0400.LENMSGR = RTVM0300.LENMSGR;
          rtvm0400.LENMSGA = RTVM0300.LENMSGA;
          rtvm0400.OFSMSGHLP = RTVM0300.OFSMSGHLP + sizeAdj;
          rtvm0400.LENMSGHLPR = RTVM0300.LENMSGHLPR;
          rtvm0400.LENMSGHLPA = RTVM0300.LENMSGHLPA;
          rtvm0400.OFSVARFMT = RTVM0300.OFSVARFMT + sizeAdj;
          rtvm0400.LENVARFMTR = RTVM0300.LENVARFMTR;
          rtvm0400.LENVARFMTA = RTVM0300.LENVARFMTA;
          rtvm0400.LENVARFMTE = RTVM0300.LENVARFMTE;
          rtvm0400.DATA = RTVM0300.DATA;
       Endif;

       If (rtvm0400.crtDate = '');
          rtvm0400.crtDate = cLowDat7;
       Endif;

       If (rtvm0400.modDate = '');
          rtvm0400.modDate = cLowDat7;
       Endif;

       Return rtvm0400;

      /END-FREE
     P                 E

       //==================================================================*
       //  Create a new RTVM0300 format.
       //==================================================================*
     P f_newRtvm0300...
     P                 B
     D                 PI                  likeds(RTVM0300_t)

       //  Fields
     D RTVM0300        DS                  likeds(rtvm0300_t) inz
       // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
      /FREE

       Clear RTVM0300;

       Return RTVM0300;

      /END-FREE
     P f_newRtvm0300...
     P                 E

       //==================================================================*
       //  Create a new rtvm0400 format.
       //==================================================================*
     P f_newRtvm0400...
     P                 B
     D                 PI                  likeds(RTVM0400_t)

       //  Fields
     D rtvm0400        DS                  likeds(rtvm0400_t) inz
       // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
      /FREE

       Clear rtvm0400;

       rtvm0400.crtDate = cLowDat7;
       rtvm0400.modDate = cLowDat7;

       Return rtvm0400;

      /END-FREE
     P                 E

       //==================================================================*
       //  Convert string to lower case.
       //==================================================================*
     P f_toLower...
     P                 B
     D                 PI          1024A          varying
     D  i_string                   1024A   const  varying

       //  Return value
     D  lowerString    S           1024A   varying inz

       //  Conversion constants
     D lc              C                   const('abcdefghijklmnopqrstuvwxyz')
     D uc              C                   const('ABCDEFGHIJKLMNOPQRSTUVWXYZ')
       // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
      /FREE

       If (%len(i_string) > 0);
          lowerString = %xlate(uc: lc: i_string);
       Else;
          lowerString = '';
       Endif;

       Return lowerString;

      /END-FREE
     P                 E

       //==================================================================*
       //  Retrieve command values
       //==================================================================*
     P f_rtvCmdValues...
     P                 B
     D                 PI          8192A          varying
     D  i_msgID                       7A   value
     D  i_msgF                       10A   value
     D  i_lib                        10A   value

       //  Return value
     D cmdValues       S           8192A   varying inz

       //  Fields
     D msgHelp         S           1024A   inz
     D rplVars         S           1024A   inz
     D qMsgF           DS                  likeds(qObj_t) inz
     D rtvm0400        DS                  likeds(rtvm0400_t) inz
     D errCode         DS                  likeds(errCode_t) inz
       //-------------------------------------------------------------------
      /FREE

       qMsgF.name = i_msgF;
       qMsgF.lib = i_lib;
       rtvm0400 = f_rtvMsgD(i_msgID: qMsgF: cMSGID_SAME: errCode);

       If (f_isApiErr(errCode) or rtvm0400.bytAvl = 0);
          cmdValues = '';
       Else;

          //  Get second level text
          msgHelp = f_rtvMsgHelp(rtvm0400);
          If (msgHelp = '');
             msgHelp = '*N';
          Else;
             msgHelp = cQuote + %trimR(msgHelp) + cQuote;
          Endif;

          //  Get replacement variables
          rplVars = f_rtvRplVars(rtvm0400);
          If (rplVars = '');
             rplVars = '*N';
          Endif;

          //  Produce CHGMSGD command
          cmdValues = ' ' +
             'MSG(' + cQuote + %trimR(f_rtvMsgText(rtvm0400)) + cQuote + ') ' +
             'SECLVL(' + %trimR(msgHelp) + ') ' +
             'FMT(' + %trimR(rplVars) + ') ' +
             'SEV(' + %char(rtvm0400.MSGSEV) + ') ';
       Endif;

       Return cmdValues;

      /END-FREE
     P                 E

